package ai.xzkj.recruitment.browsercompanion;
import ai.xzkj.recruitment.auth.SystemUser;import ai.xzkj.recruitment.boss.BossAccount;import ai.xzkj.recruitment.candidates.CandidateJobContact;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="browser_conversation_bindings") public class BrowserConversationBinding{
 @Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="boss_account_id")private BossAccount account;@OneToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="contact_id")private CandidateJobContact contact;@Column(name="external_chat_key",nullable=false,length=64)private String externalChatKey;@Column(name="display_hint",length=120)private String displayHint;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="created_by")private SystemUser createdBy;@Column(name="created_at",nullable=false)private Instant createdAt;protected BrowserConversationBinding(){}public BrowserConversationBinding(BossAccount a,CandidateJobContact c,String key,String hint,SystemUser u){id=UUID.randomUUID();account=a;contact=c;externalChatKey=key;displayHint=hint;createdBy=u;createdAt=Instant.now();}public UUID getId(){return id;}public BossAccount getAccount(){return account;}public CandidateJobContact getContact(){return contact;}public String getDisplayHint(){return displayHint;}public Instant getCreatedAt(){return createdAt;}
}
